CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY,owner TEXT NOT NULL UNIQUE,name TEXT NOT NULL,mode TEXT NOT NULL,supplies INTEGER NOT NULL,intel INTEGER NOT NULL,influence INTEGER NOT NULL,policy TEXT NOT NULL,season INTEGER NOT NULL,created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,agent TEXT NOT NULL,csrf TEXT NOT NULL,expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS used_tickets(jti TEXT PRIMARY KEY,expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS missions(id TEXT PRIMARY KEY,agent TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,step INTEGER NOT NULL,score INTEGER NOT NULL,spent INTEGER NOT NULL,intel_spent INTEGER NOT NULL,seed TEXT NOT NULL,commitment TEXT NOT NULL,policy TEXT NOT NULL,events TEXT NOT NULL,created REAL NOT NULL,ready REAL,receipt TEXT,season INTEGER NOT NULL,context TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active ON missions(agent) WHERE status IN ('ACTIVE','PENDING');
CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,agent TEXT NOT NULL,mission TEXT NOT NULL UNIQUE,payload TEXT NOT NULL,hash TEXT NOT NULL,signature TEXT NOT NULL,created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS crews(id TEXT PRIMARY KEY,name TEXT NOT NULL,leader TEXT NOT NULL,code TEXT UNIQUE NOT NULL,treasury INTEGER NOT NULL,created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS members(agent TEXT PRIMARY KEY,crew TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS territory(block TEXT PRIMARY KEY,crew TEXT NOT NULL,expires REAL NOT NULL,season INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS commands(agent TEXT,request_id TEXT,request_hash TEXT,response TEXT,PRIMARY KEY(agent,request_id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,agent TEXT,event TEXT,detail TEXT,at REAL);
CREATE TABLE IF NOT EXISTS outbox(receipt TEXT PRIMARY KEY,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS social_policy(agent TEXT PRIMARY KEY,pvp INTEGER,hiring INTEGER,cap INTEGER);
CREATE TABLE IF NOT EXISTS social_objects(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS social_seats(agent TEXT PRIMARY KEY,duel TEXT NOT NULL);
